  7	public class Application {
  8	    private static final Logger logger = LoggerFactory.getLogger(Application.class);
  9	
 10	    public static void main(String[] args) {
 11	        String dbUrl = System.getenv("DB_URL");
 12	        String dbUser = System.getenv("DB_USER");
 13	        String dbPassword = System.getenv("DB_PASSWORD");
 14	        String portStr = System.getenv("PORT");
 15	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 16	
 17	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 18	            throw new IllegalArgumentException("DB_URL, DB_USER, and DB_PASSWORD environment variables must be set");
 19	        }
 20	
 21	        Database.initialize(dbUrl, dbUser, dbPassword);
 22	
 23	        Javalin app = Javalin.create()
 24	                .get("/rooms", ctx -> RoomHandler.listRooms(ctx))
 25	                .post("/reservations", ctx -> ReservationHandler.createReservation(ctx))
 26	                .get("/reservations/{id}", ctx -> ReservationHandler.getReservation(ctx))
 27	                .post("/reservations/{id}/confirmation", ctx -> ReservationHandler.confirmReservation(ctx))
 28	                .post("/reservations/{id}/cancellation", ctx -> ReservationHandler.cancelReservation(ctx))
 29	                .post("/reservations/{id}/check-in", ctx -> ReservationHandler.checkIn(ctx))
