 40	package com.pousadamareaita;
 41	
 42	import com.zaxxer.hikari.HikariConfig;
 43	import com.zaxxer.hikari.HikariDataSource;
 44	import org.slf4j.Logger;
 45	import org.slf4j.LoggerFactory;
 46	
 47	import javax.sql.DataSource;
 48	import java.sql.Connection;
 49	import java.sql.SQLException;
 50	import java.sql.Statement;
 51	
 52	public class Database {
 53	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
 54	    private static DataSource dataSource;
 55	
 56	    public static void initialize(String dbUrl, String dbUser, String dbPassword) {
 57	        HikariConfig config = new HikariConfig();
 58	        config.setJdbcUrl(dbUrl);
 59	        config.setUsername(dbUser);
 60	        config.setPassword(dbPassword);
 61	        config.setMaximumPoolSize(10);
 62	
 63	        dataSource = new HikariDataSource(config);
 64	
 65	        createSchema();
 66	        logger.info("Database initialized");
 67	    }
 68	
 69	    private static void createSchema() {
 70	        String sql = """
 71	            CREATE TABLE IF NOT EXISTS rooms (
 72	                number INTEGER PRIMARY KEY,
 73	                type VARCHAR(20) NOT NULL,
 74	                capacity INTEGER NOT NULL,
 75	                nightly_rate NUMERIC(10, 2) NOT NULL
 76	            );
 77	
 78	            CREATE TABLE IF NOT EXISTS reservations (
 79	                id SERIAL PRIMARY KEY,
 80	                room_number INTEGER NOT NULL REFERENCES rooms(number),
 81	                guest_name VARCHAR(255) NOT NULL,
 82	                guest_email VARCHAR(255) NOT NULL,
 83	                guest_cpf VARCHAR(14) NOT NULL,
 84	                check_in DATE NOT NULL,
 85	                check_out DATE NOT NULL,
 86	                guests INTEGER NOT NULL,
 87	                rate_plan VARCHAR(50) NOT NULL,
 88	                company_code VARCHAR(50),
 89	                nights INTEGER NOT NULL,
 90	                subtotal NUMERIC(10, 2) NOT NULL,
 91	                discount NUMERIC(10, 2) NOT NULL,
 92	                total NUMERIC(10, 2) NOT NULL,
 93	                status VARCHAR(20) NOT NULL,
 94	                amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 95	                refund NUMERIC(10, 2),
 96	                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 97	            );
 98	
 99	            CREATE TABLE IF NOT EXISTS messages (
100	                id SERIAL PRIMARY KEY,
101	                channel VARCHAR(50) NOT NULL,
102	                "to" VARCHAR(255) NOT NULL,
103	                subject VARCHAR(255),
104	                body TEXT NOT NULL,
105	                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
106	            );
107	
108	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
109	                (101, 'STANDARD', 2, 249.90),
110	                (102, 'STANDARD', 2, 249.90),
111	                (201, 'DELUXE', 3, 389.90),
112	                (202, 'DELUXE', 3, 389.90),
113	                (301, 'SUITE', 4, 579.90)
114	            ON CONFLICT DO NOTHING;
115	        """;
116	
117	        try (Connection conn = dataSource.getConnection();
118	             Statement stmt = conn.createStatement()) {
119	            for (String statement : sql.split(";")) {
120	                if (!statement.trim().isEmpty()) {
121	                    stmt.execute(statement);
122	                }
123	            }
124	            logger.info("Schema created successfully");
125	        } catch (SQLException e) {
126	            logger.error("Error creating schema", e);
127	            throw new RuntimeException(e);
128	        }
129	    }
130	
131	    public static DataSource getDataSource() {
132	        return dataSource;
133	    }
134	
135	    public static Connection getConnection() throws SQLException {
136	        return dataSource.getConnection();
137	    }
138	}
139	package com.pousadamareaita;
140	
141	import com.fasterxml.jackson.databind.JsonNode;
142	import com.fasterxml.jackson.databind.ObjectMapper;
143	import com.pousadamareaita.model.Reservation;
144	import com.pousadamareaita.service.ReservationService;
145	import io.javalin.http.Context;
146	import org.slf4j.Logger;
147	import org.slf4j.LoggerFactory;
148	
149	import java.math.BigDecimal;
150	import java.time.LocalDate;
151	import java.time.format.DateTimeFormatter;
152	import java.util.Map;
153	import java.util.Optional;
154	
155	public class ReservationHandler {
156	    private static final Logger logger = LoggerFactory.getLogger(ReservationHandler.class);
157	    private static final ReservationService reservationService = new ReservationService();
158	    private static final ObjectMapper objectMapper = new ObjectMapper();
159	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE;
160	
161	    public static void createReservation(Context ctx) {
162	        try {
163	            JsonNode body = objectMapper.readTree(ctx.body());
164	
165	            if (!hasRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf",
166	                                  "checkIn", "checkOut", "guests", "ratePlan")) {
167	                sendError(ctx, "INVALID_REQUEST", "Missing required fields", 400);
168	                return;
169	            }
170	
171	            int roomNumber = body.get("roomNumber").asInt();
172	            String guestName = body.get("guestName").asText();
173	            String guestEmail = body.get("guestEmail").asText();
174	            String guestCpf = body.get("guestCpf").asText();
175	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").asText(), dateFormatter);
176	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").asText(), dateFormatter);
177	            int guests = body.get("guests").asInt();
178	            String ratePlan = body.get("ratePlan").asText();
179	            String companyCode = body.has("companyCode") ? body.get("companyCode").asText() : null;
180	
181	            Reservation reservation = reservationService.createReservation(
182	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode
183	            );
184	
185	            ctx.status(201);
186	            ctx.json(reservationToJson(reservation));
187	        } catch (ReservationService.ApiException e) {
188	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
189	        } catch (Exception e) {
190	            logger.error("Error creating reservation", e);
191	            sendError(ctx, "INVALID_REQUEST", "Invalid request body", 400);
192	        }
193	    }
194	
195	    public static void getReservation(Context ctx) {
196	        try {
197	            long id = Long.parseLong(ctx.pathParam("id"));
198	            Optional<Reservation> reservationOpt = reservationService.getReservation(id);
199	
200	            if (reservationOpt.isEmpty()) {
201	                sendError(ctx, "RESERVATION_NOT_FOUND", "Reservation not found", 404);
202	                return;
203	            }
204	
205	            ctx.json(reservationToJson(reservationOpt.get()));
206	        } catch (ReservationService.ApiException e) {
207	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
208	        } catch (Exception e) {
209	            logger.error("Error fetching reservation", e);
210	            sendError(ctx, "INVALID_REQUEST", "Invalid reservation ID", 400);
211	        }
212	    }
213	
214	    public static void confirmReservation(Context ctx) {
215	        try {
216	            long id = Long.parseLong(ctx.pathParam("id"));
217	            JsonNode body = objectMapper.readTree(ctx.body());
218	
219	            if (!body.has("amountPaid")) {
220	                sendError(ctx, "INVALID_REQUEST", "Missing amountPaid field", 400);
221	                return;
222	            }
223	
224	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").asText());
225	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
226	
227	            ctx.json(reservationToJson(reservation));
228	        } catch (ReservationService.ApiException e) {
229	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
230	        } catch (Exception e) {
231	            logger.error("Error confirming reservation", e);
232	            sendError(ctx, "INVALID_REQUEST", "Invalid request", 400);
233	        }
234	    }
235	
236	    public static void cancelReservation(Context ctx) {
237	        try {
238	            long id = Long.parseLong(ctx.pathParam("id"));
239	            Reservation reservation = reservationService.cancelReservation(id);
240	
241	            ctx.json(reservationToJson(reservation));
242	        } catch (ReservationService.ApiException e) {
243	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
244	        } catch (Exception e) {
245	            logger.error("Error cancelling reservation", e);
246	            sendError(ctx, "INVALID_REQUEST", "Invalid reservation ID", 400);
247	        }
248	    }
249	
250	    public static void checkIn(Context ctx) {
251	        try {
252	            long id = Long.parseLong(ctx.pathParam("id"));
253	            Reservation reservation = reservationService.checkIn(id);
254	
255	            ctx.json(reservationToJson(reservation));
256	        } catch (ReservationService.ApiException e) {
257	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
258	        } catch (Exception e) {
259	            logger.error("Error checking in", e);
260	            sendError(ctx, "INVALID_REQUEST", "Invalid reservation ID", 400);
261	        }
262	    }
263	
264	    public static void checkOut(Context ctx) {
265	        try {
266	            long id = Long.parseLong(ctx.pathParam("id"));
267	            Reservation reservation = reservationService.checkOut(id);
268	
269	            Map<String, Object> document = createDocument(reservation);
270	            ctx.json(document);
271	        } catch (ReservationService.ApiException e) {
272	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
273	        } catch (Exception e) {
274	            logger.error("Error checking out", e);
275	            sendError(ctx, "INVALID_REQUEST", "Invalid reservation ID", 400);
276	        }
277	    }
278	
279	    public static void getDocument(Context ctx) {
280	        try {
281	            long id = Long.parseLong(ctx.pathParam("id"));
282	            Optional<Reservation> reservationOpt = reservationService.getReservation(id);
283	
284	            if (reservationOpt.isEmpty()) {
285	                sendError(ctx, "RESERVATION_NOT_FOUND", "Reservation not found", 404);
286	                return;
287	            }
288	
289	            Reservation reservation = reservationOpt.get();
290	            if (reservation.getStatus() == Reservation.Status.PENDING) {
291	                sendError(ctx, "OPERATION_NOT_ALLOWED", "Document only available for paid reservations", 409);
292	                return;
293	            }
294	
295	            Map<String, Object> document = createDocument(reservation);
296	            ctx.json(document);
297	        } catch (ReservationService.ApiException e) {
298	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
299	        } catch (Exception e) {
300	            logger.error("Error fetching document", e);
301	            sendError(ctx, "INVALID_REQUEST", "Invalid reservation ID", 400);
302	        }
303	    }
304	
305	    private static Map<String, Object> createDocument(Reservation reservation) {
306	        String roomType = switch (reservation.getRoomNumber()) {
307	            case 101, 102 -> "STANDARD";
308	            case 201, 202 -> "DELUXE";
309	            case 301 -> "SUITE";
310	            default -> "UNKNOWN";
311	        };
312	
313	        Map<String, Object> map = new java.util.LinkedHashMap<>();
314	        map.put("title", "Comprovante de reserva");
315	        map.put("reservationId", reservation.getId());
316	        map.put("guestName", reservation.getGuestName());
317	        map.put("guestCpf", reservation.getGuestCpf());
318	        map.put("roomNumber", reservation.getRoomNumber());
319	        map.put("roomType", roomType);
320	        map.put("checkIn", reservation.getCheckIn());
321	        map.put("checkOut", reservation.getCheckOut());
322	        map.put("nights", reservation.getNights());
323	        map.put("subtotal", reservation.getSubtotal());
324	        map.put("discount", reservation.getDiscount());
325	        map.put("total", reservation.getTotal());
326	        return map;
327	    }
328	
329	    private static Map<String, Object> reservationToJson(Reservation reservation) {
330	        Map<String, Object> map = new java.util.LinkedHashMap<>();
331	        map.put("id", reservation.getId());
332	        map.put("roomNumber", reservation.getRoomNumber());
333	        map.put("guestName", reservation.getGuestName());
334	        map.put("guestEmail", reservation.getGuestEmail());
335	        map.put("guestCpf", reservation.getGuestCpf());
336	        map.put("checkIn", reservation.getCheckIn());
337	        map.put("checkOut", reservation.getCheckOut());
338	        map.put("guests", reservation.getGuests());
339	        map.put("ratePlan", reservation.getRatePlan());
340	        map.put("nights", reservation.getNights());
341	        map.put("subtotal", reservation.getSubtotal());
342	        map.put("discount", reservation.getDiscount());
343	        map.put("total", reservation.getTotal());
344	        map.put("status", reservation.getStatus());
345	        map.put("amountPaid", reservation.getAmountPaid());
346	        map.put("refund", reservation.getRefund());
347	        return map;
348	    }
349	
350	    private static boolean hasRequiredFields(JsonNode node, String... fields) {
351	        for (String field : fields) {
352	            if (!node.has(field)) {
353	                return false;
354	            }
355	        }
356	        return true;
357	    }
358	
359	    private static void sendError(Context ctx, String code, String message, int statusCode) {
360	        ctx.status(statusCode);
361	        ctx.json(Map.of("error", code, "message", message));
362	    }
363	}

