 15	
 16	public class ReservationService {
 17	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
 18	    private static final ReservationRepository reservationRepo = new ReservationRepository();
 19	    private static final RoomRepository roomRepo = new RoomRepository();
 20	    private static final Map<String, Boolean> VALID_RATE_PLANS = Map.of(
 21	        "STANDARD", true,
 22	        "NON_REFUNDABLE", true,
 23	        "CORPORATE", true,
 24	        "WEEKEND_PACKAGE", true,
 25	        "LONG_STAY", true
 26	    );
 27	
 28	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
 29	                                         String guestCpf, LocalDate checkIn, LocalDate checkOut,
 30	                                         int guests, String ratePlan, String companyCode) {
 31	
 32	        Optional<Room> roomOpt = roomRepo.findByNumber(roomNumber);
 33	        if (roomOpt.isEmpty()) {
 34	            throw new ApiException("ROOM_NOT_FOUND", "Room not found", 404);
 35	        }
 36	
 37	        Room room = roomOpt.get();
 38	
 39	        if (!VALID_RATE_PLANS.getOrDefault(ratePlan, false)) {
 40	            throw new ApiException("INVALID_REQUEST", "Invalid rate plan", 400);
 41	        }
 42	
 43	        if (guests < 1 || guests > room.getCapacity()) {
 44	            throw new ApiException("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity", 422);
 45	        }
 46	
 47	        if (!checkOut.isAfter(checkIn)) {
 48	            throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in", 400);
 49	        }
 50	
 51	        validateRatePlanRules(checkIn, checkOut, ratePlan, companyCode, room);
 52	
 53	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 54	            throw new ApiException("ROOM_UNAVAILABLE", "Room is unavailable for selected dates", 409);
 55	        }
 56	
 57	        PricingCalculator.PricingResult pricing = PricingCalculator.calculatePrice(
 58	            roomNumber, checkIn, checkOut, ratePlan, companyCode, room.getNightlyRate()
 59	        );
 60	
 61	        Reservation reservation = new Reservation(
 62	            roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
 63	            ratePlan, companyCode, pricing.nights, pricing.subtotal, pricing.discount, pricing.total
 64	        );
 65	
 66	        return reservationRepo.save(reservation);
 67	    }
 68	
 69	    public Reservation confirmReservation(long reservationId, java.math.BigDecimal amountPaid) {
 70	        Optional<Reservation> reservationOpt = reservationRepo.findById(reservationId);
 71	        if (reservationOpt.isEmpty()) {
 72	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
 73	        }
 74	
 75	        Reservation reservation = reservationOpt.get();
 76	
 77	        if (reservation.getStatus() != Reservation.Status.PENDING) {
 78	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only confirm pending reservations", 409);
 79	        }
 80	
 81	        reservation.setStatus(Reservation.Status.CONFIRMED);
 82	        reservation.setAmountPaid(amountPaid);
 83	        reservationRepo.update(reservation);
 84	
 85	        EmailService.sendConfirmationEmail(reservation);
 86	
 87	        return reservation;
 88	    }
 89	
 90	    public Reservation cancelReservation(long reservationId) {
 91	        Optional<Reservation> reservationOpt = reservationRepo.findById(reservationId);
 92	        if (reservationOpt.isEmpty()) {
 93	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
 94	        }
 95	
 96	        Reservation reservation = reservationOpt.get();
 97	
 98	        if (reservation.getStatus() == Reservation.Status.CHECKED_IN ||
 99	            reservation.getStatus() == Reservation.Status.CHECKED_OUT ||
100	            reservation.getStatus() == Reservation.Status.CANCELLED) {
101	            throw new ApiException("OPERATION_NOT_ALLOWED", "Cannot cancel this reservation", 409);
102	        }
103	
104	        java.math.BigDecimal refund = PricingCalculator.calculateRefund(
105	            reservation.getRatePlan(), reservation.getAmountPaid()
106	        );
107	
108	        reservation.setStatus(Reservation.Status.CANCELLED);
109	        reservation.setRefund(refund);
110	        reservationRepo.update(reservation);
111	
112	        return reservation;
113	    }
114	
115	    public Reservation checkIn(long reservationId) {
116	        Optional<Reservation> reservationOpt = reservationRepo.findById(reservationId);
117	        if (reservationOpt.isEmpty()) {
118	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
119	        }
120	
121	        Reservation reservation = reservationOpt.get();
122	
123	        if (reservation.getStatus() != Reservation.Status.CONFIRMED) {
124	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only check-in confirmed reservations", 409);
125	        }
126	
127	        reservation.setStatus(Reservation.Status.CHECKED_IN);
128	        reservationRepo.update(reservation);
129	
130	        return reservation;
131	    }
132	
133	    public Reservation checkOut(long reservationId) {
134	        Optional<Reservation> reservationOpt = reservationRepo.findById(reservationId);
135	        if (reservationOpt.isEmpty()) {
136	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
137	        }
138	
139	        Reservation reservation = reservationOpt.get();
140	
141	        if (reservation.getStatus() != Reservation.Status.CHECKED_IN) {
142	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only check-out from checked-in state", 409);
143	        }
144	
145	        reservation.setStatus(Reservation.Status.CHECKED_OUT);
146	        reservationRepo.update(reservation);
147	
148	        return reservation;
149	    }
150	
151	    public Optional<Reservation> getReservation(long reservationId) {
152	        return reservationRepo.findById(reservationId);
153	    }
154	
155	    private void validateRatePlanRules(LocalDate checkIn, LocalDate checkOut, String ratePlan,
156	                                      String companyCode, Room room) {
157	        if ("CORPORATE".equals(ratePlan)) {
158	            if (companyCode == null || !isCorporateCodeValid(companyCode)) {
159	                throw new ApiException("INVALID_REQUEST", "Invalid or missing company code", 400);
160	            }
161	        } else if ("WEEKEND_PACKAGE".equals(ratePlan)) {
162	            if (!isWeekendPackage(checkIn, checkOut)) {
163	                throw new ApiException("INVALID_REQUEST", "Weekend package must be Friday to Sunday (2 nights)", 400);
164	            }
165	        } else if ("LONG_STAY".equals(ratePlan)) {
166	            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
167	            if (nights < 7) {
168	                throw new ApiException("INVALID_REQUEST", "Long stay requires minimum 7 nights", 400);
169	            }
170	        }
171	    }
172	
173	    private boolean isCorporateCodeValid(String code) {
174	        return code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA");
175	    }
176	
177	    private boolean isWeekendPackage(LocalDate checkIn, LocalDate checkOut) {
178	        java.time.DayOfWeek inDay = checkIn.getDayOfWeek();
179	        java.time.DayOfWeek outDay = checkOut.getDayOfWeek();
180	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
181	
182	        return inDay == java.time.DayOfWeek.FRIDAY &&
183	               outDay == java.time.DayOfWeek.SUNDAY &&
184	               nights == 2;
185	    }
186	
187	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
188	        LocalDate current = checkIn;
189	        while (current.isBefore(checkOut)) {
190	            List<Reservation> reservations = reservationRepo.findByRoomAndDate(roomNumber, current);
191	            if (!reservations.isEmpty()) {
192	                return true;
193	            }
194	            current = current.plusDays(1);
195	        }
196	        return false;
197	    }
198	
199	    public static class ApiException extends RuntimeException {
200	        public final String code;
201	        public final int statusCode;
202	
203	        public ApiException(String code, String message, int statusCode) {
204	            super(message);
205	            this.code = code;
206	            this.statusCode = statusCode;
207	        }
208	    }
209	}
210	package com.pousadamareaita.util;
211	
212	import java.math.BigDecimal;
213	import java.math.RoundingMode;
214	import java.time.LocalDate;
215	import java.util.Map;
216	
217	public class PricingCalculator {
218	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
219	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
220	        "TECNOSUL", new BigDecimal("0.12"),
221	        "AGROVALE", new BigDecimal("0.18"),
222	        "FARMAVIDA", new BigDecimal("0.25")
223	    );
224	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
225	    private static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
226	    private static final Map<Integer, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
227	        101, new BigDecimal("520.00"),
228	        102, new BigDecimal("520.00"),
229	        201, new BigDecimal("820.00"),
230	        202, new BigDecimal("820.00"),
231	        301, new BigDecimal("1200.00")
232	    );
233	
234	    public static class PricingResult {
235	        public final int nights;
236	        public final BigDecimal subtotal;
237	        public final BigDecimal discount;
238	        public final BigDecimal total;
239	
240	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
241	            this.nights = nights;
242	            this.subtotal = subtotal;
243	            this.discount = discount;
244	            this.total = total;
245	        }
246	    }
247	
248	    public static PricingResult calculatePrice(int roomNumber, LocalDate checkIn, LocalDate checkOut,
249	                                               String ratePlan, String companyCode, BigDecimal nightlyRate) {
250	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
251	
252	        if ("WEEKEND_PACKAGE".equals(ratePlan)) {
253	            return calculateWeekendPackage(roomNumber, nights);
254	        }
255	
256	        BigDecimal subtotal = calculateSubtotal(checkIn, checkOut, nightlyRate, ratePlan);
257	
258	        BigDecimal discount = BigDecimal.ZERO;
259	        if ("NON_REFUNDABLE".equals(ratePlan)) {
260	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
261	                .setScale(2, RoundingMode.HALF_EVEN);
262	        } else if ("CORPORATE".equals(ratePlan)) {
263	            BigDecimal discountRate = CORPORATE_DISCOUNTS.getOrDefault(companyCode, BigDecimal.ZERO);
264	            discount = subtotal.multiply(discountRate)
265	                .setScale(2, RoundingMode.HALF_EVEN);
266	        } else if ("LONG_STAY".equals(ratePlan)) {
267	            discount = subtotal.multiply(LONG_STAY_DISCOUNT)
268	                .setScale(2, RoundingMode.HALF_EVEN);
269	        }
270	
271	        BigDecimal total = subtotal.subtract(discount)
272	            .setScale(2, RoundingMode.HALF_EVEN);
273	
274	        return new PricingResult(nights, subtotal, discount, total);
275	    }
276	
277	    private static PricingResult calculateWeekendPackage(int roomNumber, int nights) {
278	        BigDecimal price = WEEKEND_PACKAGE_PRICES.get(roomNumber);
279	        if (price == null) {
280	            throw new IllegalArgumentException("Room not found for weekend package");
281	        }
282	        return new PricingResult(nights, price, BigDecimal.ZERO, price);
283	    }
284	
285	    private static BigDecimal calculateSubtotal(LocalDate checkIn, LocalDate checkOut,
286	                                                BigDecimal nightlyRate, String ratePlan) {
287	        BigDecimal total = BigDecimal.ZERO;
288	        LocalDate current = checkIn;
289	
290	        while (current.isBefore(checkOut)) {
291	            BigDecimal dayRate = nightlyRate;
292	
293	            if (isHighSeason(current)) {
294	                dayRate = nightlyRate.multiply(HIGH_SEASON_MULTIPLIER);
295	            }
296	
297	            total = total.add(dayRate.setScale(2, RoundingMode.HALF_EVEN));
298	            current = current.plusDays(1);
299	        }
300	
301	        return total.setScale(2, RoundingMode.HALF_EVEN);
302	    }
303	
304	    private static boolean isHighSeason(LocalDate date) {
305	        int month = date.getMonthValue();
306	        int day = date.getDayOfMonth();
307	
308	        return (month == 7) ||
309	               (month == 12) ||
310	               (month == 1) ||
311	               (month == 2);
312	    }
313	
314	    public static BigDecimal calculateRefund(String ratePlan, BigDecimal amountPaid) {
315	        if ("NON_REFUNDABLE".equals(ratePlan)) {
316	            return BigDecimal.ZERO;
317	        } else if ("WEEKEND_PACKAGE".equals(ratePlan)) {
318	            return amountPaid.multiply(new BigDecimal("0.5"))
319	                .setScale(2, RoundingMode.HALF_EVEN);
320	        } else {
321	            return amountPaid;
322	        }
323	    }
324	}
