326	
327	import com.pousadamareaita.model.Message;
328	import com.pousadamareaita.model.Reservation;
329	import com.pousadamareaita.repository.MessageRepository;
330	
331	import java.time.format.DateTimeFormatter;
332	
333	public class EmailService {
334	    private static final MessageRepository messageRepo = new MessageRepository();
335	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
336	
337	    public static void sendConfirmationEmail(Reservation reservation) {
338	        String cpfFormatted = formatCpf(reservation.getGuestCpf());
339	        String checkInFormatted = reservation.getCheckIn().format(dateFormatter);
340	        String checkOutFormatted = reservation.getCheckOut().format(dateFormatter);
341	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
342	
343	        StringBuilder body = new StringBuilder();
344	        body.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
345	        body.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
346	        body.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
347	        body.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ").append(cpfFormatted).append(")\n");
348	        body.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(getQuartoType(reservation.getRoomNumber())).append(")\n");
349	        body.append("Entrada: ").append(checkInFormatted).append(" | Saída: ").append(checkOutFormatted).append(" | ").append(nightsText).append("\n");
350	        body.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
351	
352	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
353	            body.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
354	        }
355	
356	        body.append("Total: ").append(formatCurrency(reservation.getTotal())).append("\n\n");
357	        body.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
358	        body.append("Até breve!");
359	
360	        Message message = new Message(
361	            "EMAIL",
362	            reservation.getGuestEmail(),
363	            "Reserva confirmada - Pousada Maré Alta",
364	            body.toString()
365	        );
366	
367	        messageRepo.save(message);
368	    }
369	
370	    private static String formatCpf(String cpf) {
371	        if (cpf == null || cpf.length() != 11) {
372	            return cpf;
373	        }
374	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
375	               cpf.substring(6, 9) + "-" + cpf.substring(9);
376	    }
377	
378	    private static String getQuartoType(int roomNumber) {
379	        return switch (roomNumber) {
380	            case 101, 102 -> "STANDARD";
381	            case 201, 202 -> "DELUXE";
382	            case 301 -> "SUITE";
383	            default -> "UNKNOWN";
384	        };
385	    }
386	
387	    private static String formatCurrency(java.math.BigDecimal value) {
388	        return "R$ " + String.format("%.2f", value).replace(".", ",");
389	    }
390	}

