353	import java.time.LocalDate;
354	import java.time.format.DateTimeFormatter;
355	import java.util.List;
356	
357	public class ReportHandler {
358	    private static final Logger logger = LoggerFactory.getLogger(ReportHandler.class);
359	    private static final ReservationRepository reservationRepo = new ReservationRepository();
360	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE;
361	    private static final DateTimeFormatter csvDateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
362	
363	    public static void occupancy(Context ctx) {
364	        try {
365	            String dateStr = ctx.queryParam("date");
366	            if (dateStr == null) {
367	                ctx.status(400);
368	                ctx.json(java.util.Map.of("error", "INVALID_REQUEST", "message", "Missing date parameter"));
369	                return;
370	            }
371	
372	            LocalDate date = LocalDate.parse(dateStr, dateFormatter);
373	            List<Reservation> reservations = reservationRepo.findByDate(date);
374	
375	            StringBuilder csv = new StringBuilder();
376	            csv.append("room,type,reservation,check_in,check_out\n");
377	
378	            for (Reservation reservation : reservations) {
379	                String type = switch (reservation.getRoomNumber()) {
380	                    case 101, 102 -> "STANDARD";
381	                    case 201, 202 -> "DELUXE";
382	                    case 301 -> "SUITE";
383	                    default -> "UNKNOWN";
384	                };
385	
386	                String checkInStr = reservation.getCheckIn().format(csvDateFormatter);
387	                String checkOutStr = reservation.getCheckOut().format(csvDateFormatter);
388	
389	                csv.append(reservation.getRoomNumber()).append(",")
390	                   .append(type).append(",")
391	                   .append(reservation.getId()).append(",")
392	                   .append(checkInStr).append(",")
393	                   .append(checkOutStr).append("\n");
394	            }
395	
396	            csv.append("total,").append(reservations.size()).append("/5\n");
397	
398	            ctx.contentType("text/csv; charset=utf-8");
399	            ctx.result(csv.toString());
400	        } catch (Exception e) {
401	            logger.error("Error generating occupancy report", e);
402	            ctx.status(400);
403	            ctx.json(java.util.Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
404	        }
405	    }
406	
407	    public static void revenue(Context ctx) {
408	        try {
409	            String monthStr = ctx.queryParam("month");
410	            if (monthStr == null) {
411	                ctx.status(400);
412	                ctx.json(java.util.Map.of("error", "INVALID_REQUEST", "message", "Missing month parameter"));
413	                return;
414	            }
415	
416	            String[] parts = monthStr.split("-");
417	            if (parts.length != 2) {
418	                ctx.status(400);
419	                ctx.json(java.util.Map.of("error", "INVALID_REQUEST", "message", "Invalid month format (use YYYY-MM)"));
420	                return;
421	            }
422	
423	            int year = Integer.parseInt(parts[0]);
424	            int month = Integer.parseInt(parts[1]);
425	
426	            List<Reservation> reservations = reservationRepo.findByMonth(month, year);
427	
428	            StringBuilder csv = new StringBuilder();
429	            csv.append("reservation,room,check_in,check_out,status,amount\n");
430	
431	            BigDecimal total = BigDecimal.ZERO;
432	
433	            for (Reservation reservation : reservations) {
434	                String checkInStr = reservation.getCheckIn().format(csvDateFormatter);
435	                String checkOutStr = reservation.getCheckOut().format(csvDateFormatter);
436	
437	                BigDecimal amount = reservation.getAmountPaid();
438	                if (reservation.getRefund() != null) {
439	                    amount = amount.subtract(reservation.getRefund());
440	                }
441	
442	                csv.append(reservation.getId()).append(",")
443	                   .append(reservation.getRoomNumber()).append(",")
444	                   .append(checkInStr).append(",")
445	                   .append(checkOutStr).append(",")
446	                   .append(reservation.getStatus()).append(",")
447	                   .append(String.format("%.2f", amount).replace(",", ".")).append("\n");
448	
449	                total = total.add(amount);
450	            }
451	
452	            csv.append("total,,,,").append(String.format("%.2f", total).replace(",", ".")).append("\n");
453	
454	            ctx.contentType("text/csv; charset=utf-8");
455	            ctx.result(csv.toString());
456	        } catch (Exception e) {
457	            logger.error("Error generating revenue report", e);
458	            ctx.status(400);
459	            ctx.json(java.util.Map.of("error", "INVALID_REQUEST", "message", "Invalid month format (use YYYY-MM)"));
460	        }
461	    }
462	}
